questionvariables.text:
/* Fixed conceptual question (no randomisation). Option values are neutral literals so
   the page source does not reveal the answer; the correct option is not listed first. */
opts: [
  ["opt1", false, "Because \\(\\sin x\\) is only defined for \\(x\\) between \\(-1\\) and \\(1\\)."],
  ["opt2", true, "Because \\(\\sin x\\) is periodic, many different \\(x\\)-values give the same \\(y\\)-value, so reversing the function would not give a single output for each input."],
  ["opt3", false, "Because \\(\\sin x\\) is an odd function, and odd functions never have inverses."],
  ["opt4", false, "Because the graph of \\(y = \\sin x\\) fails the vertical line test, so \\(\\sin x\\) is not a function."]
];
